<span class="line">        <span class="token keyword">return</span> it <span class="token operator">!=</span> entityCellAppMap<span class="token punctuation">.</span><span class="token function">end</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">?</span> it<span class="token operator">-&gt;</span>second <span class="token operator">:</span> <span class="token keyword">nullptr</span><span class="token punctuation">;</span></span>
